static_assert(int(MaxLipShape::A)==PH_A&&int(MaxLipShape::E)==PH_E&&int(MaxLipShape::S)==PH_S&&int(MaxLipShape::PB)==PH_P&&int(MaxLipShape::OO)==PH_W,"Lip shapes must match existing sprite masks");
static void LipSyncChecks(const fs::path& dir){
 AppConfig app;UIConfig ui;app._appLocation=fs::absolute("RahiTuber").string()+"/";LayerManager manager;manager.Init(&app,&ui);auto* layer=manager.AddLayer();
 sf::Image asset;asset.create(16,16,{70,170,255,255});auto path=(dir/"lip.png").string();asset.saveToFile(path);
 for(auto type:{SP_IDLE,SP_TALK,SP_PH_A,SP_PH_P,SP_PH_W})layer->_sprites[type]->LoadFromTexture(&app._textureMan,path,1,1,1,12);
 layer->_swapWhenTalking=true;layer->_usePhonemes=true;layer->_lipSource=1;layer->_lipHold=0;
 auto draw=[&](MaxMouthSample mouth,bool available,float audio,PhonemeMask hint){manager._faceTracker.available=available;manager._faceTracker.mouth=mouth;layer->CalculateDraw(64,64,audio,1,hint);};
 draw(layer->_mouthCalibration.poses[1],true,0,PH_NONE);if(layer->_activeSprite!=layer->_sprites[SP_PH_A].get())throw std::runtime_error("Silent camera opening does not select A in renderer");
 layer->_lipSource=2;draw(layer->_mouthCalibration.poses[0],true,.4f,PH_A);if(layer->_activeSprite!=layer->_sprites[SP_PH_P].get())throw std::runtime_error("Combined mode ignores camera lip closure");
 draw(layer->_mouthCalibration.poses[3],true,.4f,PH_A);if(layer->_activeSprite!=layer->_sprites[SP_PH_W].get())throw std::runtime_error("Combined round mouth loses camera authority");
 draw({},false,.4f,PH_E);if(layer->_activeSprite!=layer->_sprites[SP_TALK].get())throw std::runtime_error("Missing audio fallback image hides character");
 layer->_sprites[SP_TALK]->Clear();draw({},false,.4f,PH_E);if(layer->_activeSprite!=layer->_sprites[SP_IDLE].get())throw std::runtime_error("Missing talk image hides character");
 layer->_lipSource=0;draw(layer->_mouthCalibration.poses[3],true,.4f,PH_A);if(layer->_activeSprite!=layer->_sprites[SP_PH_A].get())throw std::runtime_error("Audio mode regresses existing selection");
 draw({},false,0,PH_A);if(layer->_activeSprite!=layer->_sprites[SP_IDLE].get())throw std::runtime_error("Lost tracker keeps mouth open without audio");
 std::cout<<"PASS: actual layer selection follows camera, combined closure/rounding, silent movement, audio compatibility and missing-image fallback\n";
}

