  layer->_rigAttachLayer=parentId;layer->_attachmentBound=true;layer->_attachmentParentBase=sf::Transform::Identity;
  sf::RenderTexture canvas;canvas.create(256,256);auto attached=[&](int shape){draw(layer->_mouthBank.Pose(shape,layer->_mouthCalibration));canvas.clear(sf::Color::Transparent);layer->DrawSprites(&canvas,sf::RenderStates::Default);canvas.display();return canvas.getTexture().copyToImage();};auto a=attached(0),b=attached(8);for(unsigned y=0;y<256;++y)for(unsigned x=0;x<256;++x)if(a.getPixel(x,y)!=b.getPixel(x,y))throw std::runtime_error("Attached mixed-size mouth changes rendered bounds");
